written = 0
for cid in B01 + B02:
    assert cid in P, cid
    first, pred, basis, conf, trig = P[cid]
    assert basis.split("\n")[0] == first, cid
    rec = {"case_id": cid, "prediction_text": pred, "basis": basis, "confidence": conf, "trigger": trig}
    with open(os.path.join(BASE, cid + ".json"), "w", encoding="utf-8") as f:
        json.dump(rec, f, ensure_ascii=False, indent=1)
    written += 1
assert written == 40, written
# self-verify each file by exact path open
cnt = {"changed_main": 0, "reserve_used": 0, "disputed": 0}
for cid in B01 + B02:
    with open(os.path.join(BASE, cid + ".json"), encoding="utf-8") as f:
        r = json.load(f)
    assert r["case_id"] == cid and r["prediction_text"] and r["basis"] and 0 <= r["confidence"] <= 1
    if cid.startswith("BQ-0") and cid != "BQ-001":
        for k in cnt:
            cnt[k] += int(bool(r["trigger"][k]))
print("written", written)
print("liuyao_trigger_counts", cnt)
